row={'schema':'best-D-archive-publication-outer-v1','stable_key':'hcsn-best-full-d-asset-upload-c385-v2','argv':args,'source_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'started_utc':datetime.now(timezone.utc).isoformat(),'process_started':False,'hard_wall_seconds':2400,'publish_release':False,'training_steps':0}
def save(name,value):
 with (OUT/name).open('x') as f:f.write(json.dumps(value,indent=2,sort_keys=True)+'\n')
save('intent.json',row);p=None
try:
 with (OUT/'stdout').open('xb') as so,(OUT/'stderr').open('xb') as se:
  p=subprocess.Popen(args,stdout=so,stderr=se,start_new_session=True,env=dict(os.environ,PYTHONDONTWRITEBYTECODE='1'));row.update(process_started=True,pid=p.pid)
  try:p.wait(timeout=2400);row.update(status='completed' if p.returncode==0 else 'failed_preserved',returncode=p.returncode)
  except subprocess.TimeoutExpired:os.killpg(p.pid,signal.SIGKILL);p.wait();row.update(status='publication_wall_capped_outcome_unknown',returncode=p.returncode)
except Exception:
 row.update(status='launch_or_monitor_failed',error=traceback.format_exc())
 if p is not None and p.poll() is None:os.killpg(p.pid,signal.SIGKILL);p.wait()
finally:
 u=resource.getrusage(resource.RUSAGE_CHILDREN);row.update(complete_child_wall_seconds=time.monotonic()-start,complete_waited_child_and_descendant_CPU_seconds=u.ru_utime+u.ru_stime-usage0.ru_utime-usage0.ru_stime,child_peak_rss_bytes=u.ru_maxrss*1024,own_process_CPU_seconds=time.process_time(),finished_utc=datetime.now(timezone.utc).isoformat(),scope='Complete packaging/publication child spawn/import/all network descendants/exit. Main and command times are nested; replay was a separate earlier measured process.')
 for n in ('stdout','stderr'):
  q=OUT/n;row[n]={'bytes':q.stat().st_size,'sha256':hashlib.sha256(q.read_bytes()).hexdigest()} if q.exists() else {'missing':True}
 save('receipt.json',row);print(json.dumps(row),flush=True)
